const webhookData = $('Webhook pliego-analisis').item.json.body;
const pliego = $('Postgres - Obtener pliego').item.json;
const empresas = $('Postgres - Obtener empresas').all().map(e => e.json);
const documentosBase64 = webhookData.documentosBase64 || [];
// Leer resumen extraído por Haiku
const haikuResponse = $('Claude Haiku - Extraer documentos').item.json;
let resumenDocumentos = 'Sin documentos adjuntos.';
if (haikuResponse.content && haikuResponse.content[0] && haikuResponse.content[0].text) {
  resumenDocumentos = haikuResponse.content[0].text.trim() || 'Sin contenido extraíble.';
}
if (haikuResponse.stop_reason === 'max_tokens') {
  resumenDocumentos = '[ADVERTENCIA: resumen de documentos truncado — Haiku alcanzó max_tokens]\n' + resumenDocumentos;
}



const systemPrompt = 'Eres un asistente juridico experto en contratacion publica colombiana (SECOP II). Tu tarea tiene dos partes. PARTE 1: Analiza el pliego de condiciones adjunto y extrae la informacion clave. PARTE 2: Para cada empresa de la lista, calcula un score de compatibilidad del 0 al 100 basado en los requisitos del pliego vs el perfil de la empresa. Devuelve UNICAMENTE un JSON valido con esta estructura exacta sin texto adicional sin markdown: {"analisis_pliego":{"resumen":"string","requisitos_habilitantes":["string"],"criterios_ponderacion":[{"criterio":"string","peso":0}],"fechas_clave":[{"evento":"string","fecha":"string"}],"inconsistencias":["string"]},"comparaciones":[{"empresa_id":"string","score":0,"justificacion":"string","fortalezas_relevantes":["string"],"riesgos":["string"]}]}';

const empresasTexto = empresas.map(e => {
  const perfil = e.contexto_procesado ? JSON.stringify(e.contexto_procesado) : 'Sin perfil procesado';
  return 'Empresa ID: ' + e.id + '\nNombre: ' + e.nombre + '\nNIT: ' + e.nit + '\nSector: ' + (e.sector || 'No especificado') + '\nPerfil: ' + perfil;
}).join('\n\n---\n\n');

const introText = 'Analiza este pliego del SECOP II y las empresas candidatas.\n\nPliego: ' + pliego.nombre + (pliego.secop_id ? ' (SECOP: ' + pliego.secop_id + ')' : '') + '\n\nEMPRESAS CANDIDATAS:\n\n' + (empresas.length > 0 ? empresasTexto : 'No hay empresas con perfil listo.') + '\n\nA continuacion se adjunta el pliego en PDF.';

// Documentos resumidos por Haiku — no se envían en base64 a Sonnet

const requestBody = {
  model: 'claude-sonnet-4-6',
  max_tokens: 8192,
  system: systemPrompt,
  messages: [{ role: 'user', content: [{ type: 'text', text: userText + '\n\n=== RESUMEN DE DOCUMENTOS (extraído por IA) ===\n' + resumenDocumentos }] }]
};

return [{
  json: {
    pliegoId: webhookData.pliegoId,
    empresasIds: empresas.map(e => e.id),
    claudeBody: JSON.stringify(requestBody)
  }
}];

// FIX: respuesta truncada por max_tokens → marcar error
if ($('Claude API - Analizar pliego').item.json.stop_reason === 'max_tokens') {
  const faseId = $('Code - Build Claude Request').item.json.faseId;
  const empresaId = $('Code - Build Claude Request').item.json.empresaId;
  const pliegoId = $('Code - Build Claude Request').item.json.pliegoId;
  return [{ json: {
    ...(faseId ? { faseId } : {}),
    ...(empresaId ? { empresaId } : {}),
    ...(pliegoId ? { pliegoId } : {}),
    empresasIds: $('Code - Build Claude Request').item.json.empresasIds,
    resultado: JSON.stringify({ error: 'respuesta_incompleta', mensaje: 'Respuesta de IA truncada — documento demasiado extenso' }),
    analisisPliego: JSON.stringify({ error: 'respuesta_incompleta' }),
    comparaciones: [],
    generalData: JSON.stringify({ error: 'respuesta_incompleta' }),
    porEmpresa: JSON.stringify({})
  } }];
}

const response = $('Claude API - Analizar pliego').item.json;
const buildData = $('Code - Build Claude Request').item.json;

let rawText = '';
if (response.content && response.content[0] && response.content[0].text) {
  rawText = response.content[0].text.trim();
  rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
}

let parsed = null;
try {
  parsed = JSON.parse(rawText);
} catch(e) {
  parsed = { error: 'respuesta_no_valida', raw: rawText.substring(0, 500) };
}

const analisisPliego = parsed.analisis_pliego || parsed;
const comparaciones = Array.isArray(parsed.comparaciones) ? parsed.comparaciones : [];

return [{
  json: {
    pliegoId: buildData.pliegoId,
    empresasIds: buildData.empresasIds,
    analisisPliego: JSON.stringify(analisisPliego),
    comparaciones
  }
}];

const data = $('Code - Extract respuesta').item.json;
const webhookData = $('Webhook pliego-analisis').item.json.body;
const comparaciones = data.comparaciones;
const pliegoId = data.pliegoId;
const faseId = webhookData.faseId || null;

const inserts = comparaciones.map(comp => ({
  json: {
    pliegoId,
    faseId,
    empresaId: comp.empresa_id,
    score: Math.min(100, Math.max(0, Math.round(comp.score))),
    justificacion: comp.justificacion || '',
    fortalezas: JSON.stringify(comp.fortalezas_relevantes || []),
    riesgos: JSON.stringify(comp.riesgos || [])
  }
}));

if (inserts.length === 0) {
  return [{ json: { pliegoId, faseId, analisisPliego: data.analisisPliego, sinComparaciones: true } }];
}

return inserts.map(i => ({ json: { ...i.json, analisisPliego: data.analisisPliego } }));

const webhookData = $('Webhook pliego-analisis').item.json.body;
const documentosBase64 = webhookData.documentosBase64 || [];

const MAX_CHARS_PER_DOC = 80000;

function truncateText(text, maxChars) {
  if (!text || text.length <= maxChars) return text;
  const front = text.substring(0, Math.floor(maxChars * 0.7));
  const back = text.substring(text.length - Math.floor(maxChars * 0.25));
  return front + '\n...[OMITIDO: ' + (text.length - maxChars) + ' caracteres]...\n' + back;
}

const contentBlocks = [];
for (const doc of documentosBase64) {
  if (doc.textoExtraido) {
    contentBlocks.push({
      type: 'text',
      text: 'DOCUMENTO: ' + doc.nombre + '\n\n' + truncateText(doc.textoExtraido, MAX_CHARS_PER_DOC)
    });
  } else {
    contentBlocks.push({
      type: 'document',
      source: { type: 'base64', media_type: doc.mediaType, data: doc.base64 },
      title: doc.nombre
    });
  }
}
if (contentBlocks.length === 0) {
  contentBlocks.push({ type: 'text', text: 'Sin documentos adjuntos.' });
}

const haikuBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 4096,
  system: 'Extrae y resume en máximo 500 palabras los puntos clave del documento adjunto: requisitos habilitantes (jurídico, financiero, técnico, experiencia), criterios de ponderación con sus pesos, fechas importantes, valores del contrato, alertas o cascaritas. Responde solo con el resumen estructurado.',
  messages: [{ role: 'user', content: contentBlocks }]
};

return [{ json: { haikuBody: JSON.stringify(haikuBody) } }];
